import { Marker, NaverMap, NaverMapsProviderProps, useNavermaps } from "react-naver-maps";

const CardItem_Map = (mapx,mapy,mlevel) => {

  //npm install react-naver-maps
  //https://colinch4.github.io/2021-06-07/navermap/
  //https://navermaps.github.io/maps.js.ncp/docs/tutorial-2-Getting-Started.html  
    const navermaps = useNavermaps();

    return (
        
        <NaverMapsProviderProps ncpClientId="a303tgghr5">
          <NaverMap defaultCenter={new navermaps.LatLng(mapy,mapx)} defaultZoom={mlevel}></NaverMap>
          <Marker defaultPosition={new navermaps.LatLng(mapy,mapx)}></Marker>
        </NaverMapsProviderProps>
        
    );
}


export default CardItem_Map;
